import{af as e,z as a,J as i,ab as o}from"./chunks/framework.BnTFvF69.js";const y=JSON.parse('{"title":"Troubleshooting","description":"","frontmatter":{"aside":false},"headers":[],"relativePath":"faq/troubleshooting.md","filePath":"faq/troubleshooting.md"}'),r={name:"faq/troubleshooting.md"};function n(s,t,l,c,h,u){return a(),i("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1793263438000"},[...t[0]||(t[0]=[o('<h1 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h1><nav class="table-of-contents"><ul><li><a href="#why-are-location-updates-not-instant">Why are location updates not instant? ​</a></li><li><a href="#why-is-my-tracker-not-transmitting">Why is my tracker not transmitting? ​</a></li><li><a href="#why-is-my-tracker-giving-inaccurate-locations">Why is my tracker giving inaccurate locations? ​</a></li><li><a href="#why-is-my-battery-not-lasting-as-long-as-advertised">Why is my battery not lasting as long as advertised? ​</a></li></ul></nav><h2 id="why-are-location-updates-not-instant" tabindex="-1">Why are location updates not instant? <a class="header-anchor" href="#why-are-location-updates-not-instant" aria-label="Permalink to &quot;Why are location updates not instant?&quot;">​</a></h2><p>In many cases, location can not be retrieved instantly, it takes time to get a <a href="/docs/pr/30/terminology/positioning/gnss">GPS fix</a> and if that fails, the <a href="/docs/pr/30/terminology/positioning/">other location technologies</a> come into action.</p><p>After a device has determined its location, it has to connect to the internet via the mobile networks in order to send the location information.</p><p>Once the information has been received by our servers, during normal operation it should be visible to you within a few seconds.</p><h2 id="why-is-my-tracker-not-transmitting" tabindex="-1">Why is my tracker not transmitting? <a class="header-anchor" href="#why-is-my-tracker-not-transmitting" aria-label="Permalink to &quot;Why is my tracker not transmitting?&quot;">​</a></h2><p>Always give your tracker a couple of minutes to send a location update.</p><p>If it still hasn&#39;t sent a location update, make sure:</p><ul><li>Your device has an active data plan</li><li>Your device is charged</li><li>The tracker is in an area with good mobile coverage</li></ul><p>If you have checked the above and your tracker is still not transmitting, try the following:</p><ul><li>Force a location update (hold tracker button for 3 seconds)</li><li>Perform a reset (hold tracker button for 15 seconds)</li><li>Place the tracker outside for 5 minutes after completing all the above</li></ul><p>If the tracker is still not transmitting, please contact us.</p><h2 id="why-is-my-tracker-giving-inaccurate-locations" tabindex="-1">Why is my tracker giving inaccurate locations? <a class="header-anchor" href="#why-is-my-tracker-giving-inaccurate-locations" aria-label="Permalink to &quot;Why is my tracker giving inaccurate locations?&quot;">​</a></h2><p>Location accuracy depends on several variables.</p><p>There are a few good practices that help improve the location accuracy of your tracker.</p><ul><li>Try to place your tracker with the logo facing up (this is where the GPS antenna is located)</li><li>Avoid surrounding your tracker with metals as they block GPS and GSM signals</li><li>To allow for more GPS locations to be gathered, try to place your tracker somewhere with a good line of sight with the sky</li><li>Increase the GPS timeout.</li><li>Make sure you have the correct settings. If you are unsure, please get in touch and we will assist!</li></ul><h2 id="why-is-my-battery-not-lasting-as-long-as-advertised" tabindex="-1">Why is my battery not lasting as long as advertised? <a class="header-anchor" href="#why-is-my-battery-not-lasting-as-long-as-advertised" aria-label="Permalink to &quot;Why is my battery not lasting as long as advertised?&quot;">​</a></h2><p>The advertised values are general guidelines.</p><p>In reality, there are many variables that affect battery life, such as:</p><ul><li>Where the tracker is mounted: with a clear line of sight with the sky, the tracker will use less power per location update</li><li>Is the tracker indoors? If the tracker is indoor, more power will be used as the tracker will try to look for a GPS fix before attempting to locate itself via WPS or GSM. Find out more about this under the How the location technologies work section</li><li>Make sure you have Wi-Fi and GPS Safe Zones set up where applicable</li><li>Motion sensitivity: maybe your tracker is sending more location updates than it should because the motion sensitivity is too high. This usually occurs when the tracker is stationary but still sending location updates. Reduce the motion sensitivity via your flexible configurations page.</li></ul><p>You can always <a href="https://lightbug.io/contact/" target="_blank" rel="noreferrer">contact our support team</a> for help with this.</p>',22)])])}const g=e(r,[["render",n]]);export{y as __pageData,g as default};
